Certainly! Below is a JavaScript function that takes a string representing a dot-notation path to options within another object, and returns all entries in those options where the nested keys match the specified string.

```javascript
function getMatchingOptions(objPath, obj) {
    const [pathParts] = objPath.split('.');
    let currentObj = obj;

    for (let i = 0; i < pathParts.length - 1; i++) {
        if (!currentObj || !currentObj.hasOwnProperty(pathParts[i])) {
            throw new Error(`Invalid object path: ${objPath}`);
        }
        currentObj = currentObj[pathParts[i]];
    }

    // Get the last part of the path which should be the exact key name
    const targetKey = pathParts[pathParts.length - 1];

    // Check each entry in the final object with the same key
    const matchingEntries = [];
    for (const [key, value] of Object.entries(currentObj)) {
        if (key === targetKey) {
            matchingEntries.push(value);
        }
    }

    return matchingEntries;
}

